insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),0,'Миндальный бисквит','Белки взбить с сахаром 1 и солью до мягкого блестящего клюва (~8 минут). Яйца взбить с сахаром 2 до белой пышной пены.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),1,'Миндальный бисквит','Просеять на яйца обе муки, перемешать снизу вверх. Две ложки теста вмешать в растопленное масло и вернуть в тесто. В конце вмешать меренгу.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),2,'Миндальный бисквит','Распределить в рамке 21×26 см слоем 1,5–2 см, печь при 180 °C ~15 минут. Сразу накрыть плёнкой и охладить. Собирать в рамке с ацетатом или пергаментом по стенкам.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),3,'Компоте из помело','250 г мякоти пробить блендером, 250 г порвать кусочками. Сахар с пектином всыпать в пюре дождём, помешивая.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),4,'Компоте из помело','Довести до кипения, проварить 15–30 секунд, снять с огня, добавить лимонную кислоту и кусочки. Охладить до 50 °C, вылить на бисквит, в морозилку.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),5,'Кремю манго-апельсин','Желатин замочить 1:6. Желтки, пюре, сок, сахар и крахмал довести до кипения, помешивая, проварить 15 секунд, процедить, вмешать желатин.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),6,'Кремю манго-апельсин','Охладить до 40 °C, добавить мягкое масло, пробить блендером, сразу распределить на компоте, в морозилку.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),7,'Баварский мусс','Желатин замочить 1:6. Молоко со сливками 1 довести до кипения. Сахар, мёд и желтки смешать, влить горячую смесь, вернуть в сотейник и проварить до 83 °C, помешивая.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),8,'Баварский мусс','Процедить, вмешать желатин, охладить до 26–30 °C и вмешать полувзбитые сливки 2. Вылить на кремю, в морозилку.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),9,'Глазурь гурмэ','Шоколад растопить с маслом, добавить манго, охладить до 20–25 °C.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:oazis'),10,'Глазурь гурмэ','Замороженный пласт нарезать на пирожные 3,5×8 см, окунуть в глазурь или полить на решётке. Сразу в холодильник на 2–3 часа до дефростации.';
