insert into recipe_ingredients(recipe_id,position,section,name,base,amount,amount_max,unit,grams,approx,optional,alt_group,note,raw) select (select id from recipes where imported_from='pdf:pistachio-cake'),20,'Фисташковая глазурь','фисташки дроблёные','фисташки',30,null,'г',null,false,false,null,null,null;
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),0,'Фисташковое тесто','Духовку 150–160 °C, формы смазать и выстелить бумагой. Фисташковую пасту с яйцами прогреть до 35–38 °C и пробить блендером.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),1,'Фисташковое тесто','Мягкое масло взбить с сахаром и солью, добавить тёплую яичную смесь до эмульсии. Вручную вмешать обе муки с разрыхлителем.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),2,'Фисташковое тесто','Печь 40–50 минут. Тёплыми завернуть в плёнку и убрать в холодильник на 6–8 часов.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),3,'Сливочный крем','Холодные сыр, сливки и пудру взбить на средней скорости до стабильности.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),4,'Вишнёвое компоте','Сахар смешать с пектином. Вишню разморозить и прогреть до 20–40 °C, всыпать сахар с пектином, довести до 85 °C, проварить 15 секунд, добавить сок.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),5,'Вишнёвое компоте','Охладить до 60 °C, добавить рубленый эстрагон; при 45 °C выложить на охлаждённые кексы. Перед глазурью — 10–15 минут в морозилку.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:pistachio-cake'),6,'Фисташковая глазурь','Шоколад, пасту, масло какао и масло косточки растопить (~40 °C), добавить фисташки. Использовать при 22–28 °C.';
insert into recipes(household_id,kind,title,summary,yield_amount,yield_unit,time_min,status,tags,source_type,source_author,source_url,source_ref,original_lang,imported_from,methods,category) select h.id,'recipe','Клубничный тарт на сабле бретон с фисташковым ганашем','Тарт 16 см + 3 тарталетки 8 см. Ганашу нужно 8 часов в холодильнике. Хранение 72 часа.',16,'форма Ø, см',null,'want',array['кондитерка']::text[],'pdf','Victoria Melnik, vicky.school',null,'PDF «Клубничный тарт»','ru','pdf:strawberry-tart',array['духовка','плита']::text[],'Десерты' from households h where h.name='Наш дом' limit 1;
