insert into recipe_ingredients(recipe_id,position,section,name,base,amount,amount_max,unit,grams,approx,optional,alt_group,note,raw) select (select id from recipes where imported_from='pdf:strawberry-tart'),20,'Сборка','клубника свежая и цедра лайма','клубника',null,null,'для украшения',null,false,false,null,null,null;
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),0,'Взбитый фисташковый ганаш','Белый шоколад растопить до 45–50 °C. Сливки А с глюкозой прогреть до 50–55 °C, вылить на шоколад, добавить пасту и пробить блендером.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),1,'Взбитый фисташковый ганаш','Охладить до 40 °C, влить сливки Б, пробить. Накрыть в контакт и в холодильник на 8 часов (до 3 °C). Взбить в холодной чаше до стабильности и сразу использовать.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),2,'Сабле бретон','Мягкое масло размять, ввести пудру, желтки и треть сухих, затем остальное — не вымешивать. Пласт 1 см в плёнке в холодильник минимум на 2 часа.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),3,'Сабле бретон','Раскатать 7–10 мм, вырезать круги, уложить в кольца. Печь при 160 °C (верх/низ) 15–20 минут до золотистого цвета, остудить.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),4,'Клубничное конфи','Сахар с пектином всыпать в пюре при 30–45 °C, довести до 85 °C, снять с огня, добавить сок. Накрыть в контакт и охладить.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),5,'Фламбированная клубника','Клубнику мелким кубиком обжарить на масле 1 минуту, посыпать сахаром, влить алкоголь и поджечь. Сразу переложить и охладить — не дольше 2 минут на огне.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:strawberry-tart'),6,'Сборка','На основу — конфи и фламбированную клубнику, сверху отсадить взбитый ганаш, украсить клубникой и цедрой лайма.';
insert into recipes(household_id,kind,title,summary,yield_amount,yield_unit,time_min,status,tags,source_type,source_author,source_url,source_ref,original_lang,imported_from,methods,category) select h.id,'recipe','Вертикальный лимонный торт','Кокосовый бисквит, лимонный крем с эстрагоном, сырный ганаш, лимонный гель. Теория сборки и выравнивания — в том же PDF, стр. 5–7.',17,'форма Ø, см',null,'want',array['кондитерка']::text[],'pdf','Victoria Melnik, vicky.school',null,'PDF «Вертикальные торты» (cake_Limon)','ru','pdf:cake-lemon',array['духовка','плита']::text[],'Десерты' from households h where h.name='Наш дом' limit 1;
