insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),0,'Кокосовый бисквит','Духовку 150–160 °C. Кокосовое молоко с маслом прогреть до 40–50 °C. Белки взбить с сахаром А до мягкого клюва, желтки с сахаром Б — до утроения объёма.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),1,'Кокосовый бисквит','В желтки вмешать треть меренги и просеянные муку, крахмал, разрыхлитель. 3 ложки теста вмешать в молочную смесь и вернуть. В конце — остаток меренги.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),2,'Кокосовый бисквит','Разровнять на противне слоем 1 см, посыпать стружкой, печь ~15 минут. Остудить под плёнкой, нарезать полосами 9–10 см.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),3,'Лимонный крем','Желатин замочить 1:6. Сахар, желтки, сок и цедру прогреть до 83 °C (впервые — на водяной бане), процедить, вмешать желатин.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),4,'Лимонный крем','При 40–45 °C добавить мягкое масло и эстрагон, пробить блендером, накрыть в контакт и охладить.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),5,'Сырный ганаш','Желатин замочить 1:6. Горячие сливки вылить на шоколад, через 1–2 минуты добавить желатин и цедру, пробить. Охладить 2–3 часа, затем взбить с сыром до устойчивости.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),6,'Крем для покрытия','Мягкое масло взбить с пудрой добела, сменить на лопатку, добавить сыр комнатной температуры и ром до гладкости.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-lemon'),7,'Лимонный гель','Сахар с агаром всыпать в сок с водой, прокипятить 30 секунд. При 60 °C добавить цедру, охладить в контакт, пробить блендером.';
insert into recipes(household_id,kind,title,summary,yield_amount,yield_unit,time_min,status,tags,source_type,source_author,source_url,source_ref,original_lang,imported_from,methods,category) select h.id,'recipe','Вертикальный малиновый торт','Ванильный бисквит, малиновое конфи, ванильный сырный ганаш (650 г на сборку, 380 г на выравнивание), малиновый ганаш для покрытия.',17,'форма Ø, см',null,'want',array['кондитерка']::text[],'pdf','Victoria Melnik, vicky.school',null,'PDF «Вертикальные торты» (cake_Limon)','ru','pdf:cake-raspberry',array['духовка','плита']::text[],'Десерты' from households h where h.name='Наш дом' limit 1;
