insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),0,'Ванильный бисквит','Как кокосовый бисквит в лимонном торте, но молоко прогревается с семенами ванили и маслом. Слой 1 см, ~15 минут при 150–160 °C, полосы 9–10 см.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),1,'Малиновое конфи','Малину с водой, сахаром и ванилью довести до кипения. Половину протереть через сито и вернуть.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),2,'Малиновое конфи','Крахмал с 2 ст. л. воды влить при 60–70 °C, прокипятить 2–3 минуты до блеска. Охладить в контакт.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),3,'Сырный ганаш','Сливки с ванилью довести до кипения и настоять минимум 3 часа (лучше ночь). Желатин замочить 1:6.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),4,'Сырный ганаш','Снова довести сливки до кипения, вылить на шоколад, добавить желатин, пробить. Охладить 2–3 часа и взбить с сыром и маскарпоне до устойчивости.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cake-raspberry'),5,'Малиновый ганаш (покрытие)','Пюре с глюкозой довести до 80–90 °C, смешать с растопленным шоколадом, при 40 °C добавить масло и пробить. Покрывать при ~20 °C торт, подмороженный 30–60 минут.';
