insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cheese-pie'),0,null,'Духовку разогреть до 190 °C. Смешать творог, яйцо и масло, добавить муку с солью, сахаром и разрыхлителем. Замесить и дать постоять 10 минут.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cheese-pie'),1,null,'Сыр натереть на крупной тёрке, добавить чеснок, тимьян и сметану.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cheese-pie'),2,null,'Меньшую часть теста раскатать в круг ~25 см на смазанном противне, выложить начинку, накрыть большей частью и защипнуть.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:cheese-pie'),3,null,'Смазать яйцом с водой, посыпать кунжутом и печь ~25 минут до румяности.';
