insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galettes'),0,'Заварной крем','Молоко довести до кипения. Яйцо смешать с сахаром и крахмалом, тонкой струйкой влить молоко, помешивая.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galettes'),1,'Заварной крем','Вернуть на огонь и варить до загустения и больших пузырей. Снять, вмешать масло, процедить, накрыть плёнкой в контакт и охладить.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galettes'),2,'Тесто','Все ингредиенты теста перемешать миксером, разделить на части по ~70 г и раскатать в лепёшки.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galettes'),3,'Тесто','Тонким слоем нанести крем, сверху фрукты, загнуть края и смазать их яйцом с молоком.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galettes'),4,'Тесто','Печь при 180 °C (конвекция) 15–20 минут до золотистой корочки.';
