insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galette-fillings'),0,'Клубника с миндальным кремом','Для миндального крема смешать всё до однородности и смазать лепёшки. Клубнику слайсами выложить слоями, каждый посыпая щепоткой сахара и крахмала, сверху миндаль.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galette-fillings'),1,'Яблочная','Орехи запечь 10–12 минут при 160 °C. Яблоки тонкими слайсами на тесто (с заварным кремом или без), смазать маслом, посыпать сахаром, корицей и орехами.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galette-fillings'),2,'Вишнёвая','Вишню, сахар, корицу и воду довести до кипения, влить крахмал, разведённый в 2 ст. л. холодной воды, проварить 1–2 минуты до глянца. Остудить. Крем не нужен.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galette-fillings'),3,'Ореховое тесто','Орехи запечь и измельчить, смешать с мукой, кубиками масла, солью и сахаром. Добавить 45 г воды и подливать, пока тесто не соберётся. Охладить 30–60 минут.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:galette-fillings'),4,'Сливовая','Сливы дольками с сахаром, корицей и солью довести до кипения, влить крахмал с водой, проварить 1–2 минуты. Остудить и выложить на ореховое тесто.';
insert into recipes(household_id,kind,title,summary,yield_amount,yield_unit,time_min,status,tags,source_type,source_author,source_url,source_ref,original_lang,imported_from,methods,category) select h.id,'recipe','Творожные пончики','Солёный вариант: вместо сахара 1 ч. л. соли, чили, посыпать копчёной паприкой — закуска к вину. В сладкий можно цедру лимона или лайма.',null,null,null,'want',array['творог','во фритюре']::text[],'pdf',null,null,'PDF мастер-класса по творожной выпечке','ru','pdf:curd-donuts',array['плита']::text[],'Выпечка' from households h where h.name='Наш дом' limit 1;
