insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:curd-donuts'),1,null,'Добавить творог и сухие ингредиенты — тесто должно легко скатываться в шарики (при необходимости добавить муки).';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:curd-donuts'),2,null,'Скатать шарики размером с небольшой грецкий орех.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='pdf:curd-donuts'),3,null,'Жарить в масле при 160–180 °C до золотистого цвета, выложить на бумажное полотенце и посыпать пудрой.';
