begin;
create temp table keep_marks on commit drop as select imported_from,status,rating,notes,share_token,hidden,category from recipes where imported_from in ('pdf:box-florentin','pdf:box-fudge','pdf:box-truffle-cherry','pdf:box-truffle-tonka','pdf:box-toffee','pdf:box-brownie','pdf:box-brownie-sandwich','pdf:oazis','pdf:pistachio-cake','pdf:strawberry-tart','pdf:cake-lemon','pdf:cake-raspberry','pdf:cheese-pie','pdf:galettes','pdf:galette-fillings','pdf:curd-donuts');
delete from recipes where imported_from='pdf:box-florentin';
delete from recipes where imported_from='pdf:box-fudge';
delete from recipes where imported_from='pdf:box-truffle-cherry';
delete from recipes where imported_from='pdf:box-truffle-tonka';
delete from recipes where imported_from='pdf:box-toffee';
delete from recipes where imported_from='pdf:box-brownie';
delete from recipes where imported_from='pdf:box-brownie-sandwich';
delete from recipes where imported_from='pdf:oazis';
delete from recipes where imported_from='pdf:pistachio-cake';
delete from recipes where imported_from='pdf:strawberry-tart';
delete from recipes where imported_from='pdf:cake-lemon';
delete from recipes where imported_from='pdf:cake-raspberry';
delete from recipes where imported_from='pdf:cheese-pie';
delete from recipes where imported_from='pdf:galettes';
delete from recipes where imported_from='pdf:galette-fillings';
delete from recipes where imported_from='pdf:curd-donuts';
update recipes r set status=k.status, rating=k.rating, notes=k.notes, share_token=k.share_token, hidden=k.hidden, category=coalesce(k.category, r.category) from keep_marks k where r.imported_from=k.imported_from;
commit;